/**
 * @file    blink.c
 * @brief   The blink task's handlers (SPEC-020): each state's returns the state to be in next.
 *
 * @details
 * Generated by emb-hwgen from system.yaml; yours to edit: regeneration merges its changes (A126).
 */
#include "tasks.h"

#include <emb_board.h>

static uint32_t blinks; /* this task's own: only its thread touches it */

emb_state_t blink_on_dark(blink_t *self)
{
    (void)self;
    emb_board_led_toggle();
    return BLINK_LIT;
}

emb_state_t blink_on_lit(blink_t *self)
{
    (void)self;
    emb_board_led_toggle();
    blinks++;
    if ((blinks % 4u) == 0u) { /* every fourth blink, two seconds: the door opens */
        (void)emb_task_post(DOOR_TASK, DOOR_EV_OPEN, blinks);
    }
    return BLINK_DARK;
}
